var TZ = 'Asia/Jakarta';
var STATUSES = ['Not Started', 'In Progress', 'Completed', 'On Hold', 'Blocked'];
var PRIOS = ['High', 'Medium', 'Low'];
var RISK_TYPES = ['Risk', 'Issue', 'Decision', 'Dependency'];
var RISK_STATUSES = ['Open', 'Monitoring', 'Closed'];
